ALTER TABLE users ADD COLUMN fcm_device_token text;

-- Older clients wrote their FCM token into ntfy_topic_token. Ntfy topics
-- generated by the legacy API use the stovo-user- prefix, so preserve those
-- values in place while moving device tokens to their own column.
UPDATE users
SET fcm_device_token = ntfy_topic_token,
    ntfy_topic_token = NULL
WHERE ntfy_topic_token IS NOT NULL
  AND ntfy_topic_token NOT LIKE 'stovo-user-%';
